-- Seed data from forclaud: features (from features.py), feature_revisions (none in source), feature_results (from title_page.csv)
-- All feature ids/names/descriptions taken from forclaud/features.py. is_root and is_default set to 0 (no source data).

INSERT INTO features (id, created_at, updated_at, name, description, is_root, is_default) VALUES
('base_content', datetime('now'), datetime('now'), 'base_content', 'The minimal designation of the book''s main content, typically appearing at the beginning of the title page, without elaboration.', 0, 0),
('editor_name', datetime('now'), datetime('now'), 'editor_name', 'The name of the contemporary adapter (author, editor, translator, commentator, etc.) as it appears on the title page.', 0, 0),
('editor_description', datetime('now'), datetime('now'), 'editor_description', 'Any descriptors found alongside the adapter name, such as academic titles, ranks, or affiliations.', 0, 0),
('AUTHOR DESCRIPTION 2', datetime('now'), datetime('now'), 'AUTHOR DESCRIPTION 2', 'Any descriptors found alongside the adapter name, such as academic titles, ranks, or affiliations. (an additional quote if applicable).', 0, 0),
('dedicatee_name', datetime('now'), datetime('now'), 'dedicatee_name', 'Mentions of patrons or dedication.', 0, 0),
('edition_details', datetime('now'), datetime('now'), 'edition_details', 'Any information that is highlighted as relevant for this specific edition such as claims regarding the corrections and revisions introduced in it.', 0, 0),
('printing_privilege', datetime('now'), datetime('now'), 'printing_privilege', 'Mentions of royal privileges or legal permissions granted for printing.', 0, 0),
('action_verbs', datetime('now'), datetime('now'), 'action_verbs', 'Action verbs such as traduit (translated), commenté (commented), augmenté (expanded) that describe the role the contemporary scholar played in bringing about the work.', 0, 0),
('origin_language', datetime('now'), datetime('now'), 'origin_language', 'Mentions of the source language (e.g., Latin or Greek) and/or the target language.', 0, 0),
('educational_authorities_references', datetime('now'), datetime('now'), 'educational_authorities_references', 'Mentions of other scholars, either ancients, such as Theon of Alexandria, or contemporary, like Simon Stevin.', 0, 0),
('references_to_Euclid', datetime('now'), datetime('now'), 'references_to_Euclid', 'Euclid''s name as it appears on the title page.', 0, 0),
('description_of_Euclid', datetime('now'), datetime('now'), 'description_of_Euclid', 'Any descriptors found alongside Euclid''s name, such as mentioning him being a mathematician.', 0, 0),
('EUCLID DESCRIPTION 2', datetime('now'), datetime('now'), 'EUCLID DESCRIPTION 2', 'Any descriptors found alongside Euclid''s name, such as mentioning him being a mathematician. (an additional quote if applicable).', 0, 0),
('audience', datetime('now'), datetime('now'), 'audience', 'Explicit mentions of the work''s intended recipients or audience.', 0, 0),
('RECIPIENT 2', datetime('now'), datetime('now'), 'RECIPIENT 2', 'Explicit mentions of the work''s intended recipients or audience. (an additional quote if applicable).', 0, 0),
('Elements_designation', datetime('now'), datetime('now'), 'Elements_designation', 'The designation of the Elements, such as ''Elements of Geometry'' or ''Euclid''s Elements'', as it appears on the title page.', 0, 0),
('Greek_text', datetime('now'), datetime('now'), 'Greek_text', 'Greek designation of the book in non-Greek books.', 0, 0),
('institutions', datetime('now'), datetime('now'), 'institutions', 'Mentions of institutions, such as societies or universities, associated with the book.', 0, 0),
('bound_with', datetime('now'), datetime('now'), 'bound_with', 'Mentions of other works that are included in the work, in addition to Euclid''s Elements, such as ''Optics'', ''Data'', theorems by Archimedes. Mentions of additions ingrained in the core text and written by the adapter/translator of the text, such as examples or explanations, should not be included here. Try to mark the minimal unit of the bound work. For example, instead of marking ''cum expositione Theonis.'', mark ''expositione Theonis'' as the bound work. Try to also break down the bound works into their components. For example, instead of marking ''Phaenomena, Optics, and Catoptrics'', mark ''Phaenomena'', ''Optics'', and ''Catoptrics'' as the bound works.', 0, 0),
('enriched_with', datetime('now'), datetime('now'), 'enriched_with', 'Mentions of additional content that is not part of the core text, such as illustrations, diagrams, explanations, expositions, examples or other supplementary material that enriches the text and makes it more understandable, accurate, or useful. Mentions of other distinct works that are included in the book, in addition to Euclid''s Elements, such as ''Optics'', ''Data'', theorems by Archimedes, should not be included here. Try to mark the minimal unit of enrichment. For example, instead of marking ''To which are added some utilities'', mark ''utilities'' as the enriched content. Try to also break down the enrichment into its components, such as ''explanations'', ''examples'', ''diagrams'', etc.', 0, 0),
('date_in_imprint', datetime('now'), datetime('now'), 'date_in_imprint', 'Mentions of the date, usually in the form of a year, when the book was printed or published.', 0, 0),
('publisher_in_imprint', datetime('now'), datetime('now'), 'publisher_in_imprint', 'Mentions of the publisher or printer, such as the name of the printing house or the person responsible for the publication. Try to include the minimal unit of the publisher''s name. For example, instead of marking ''Apud Vincentium Accoltum'', mark ''Vincentium Accoltum'', and instead of marking ''Chez GVILLAVME AVVRAY, au haut de la ruë sainct Iean de Beauuais, au Bellerophon couronné'', mark ''GVILLAVME AVVRAY''.', 0, 0),
('location_in_imprint', datetime('now'), datetime('now'), 'location_in_imprint', 'Mentions of the city or town where the book was printed or published. Do not include full addresses, just the city or town name. For example, instead of marking ''A Paris, chez GVILLAVME AVVRAY, au haut de la ruë sainct Iean de Beauuais, au Bellerophon couronné'', mark ''Paris''.', 0, 0),
('printing_privilege_in_imprint', datetime('now'), datetime('now'), 'printing_privilege_in_imprint', 'Mentions of royal privileges or legal permissions granted for printing.', 0, 0),
('dedication_in_imprint', datetime('now'), datetime('now'), 'dedication_in_imprint', 'Mentions of patrons or dedications.', 0, 0),
('editor_in_imprint', datetime('now'), datetime('now'), 'editor_in_imprint', 'The name of the contemporary adapter (author, editor, translator, commentator, etc.) as it appears on the title page. Do not include any descriptors, just the name itself. Do not include the printer or publisher''s name, just the adapter''s name, if exists.', 0, 0),
('editor_description_in_imprint', datetime('now'), datetime('now'), 'editor_description_in_imprint', 'Any descriptors found alongside the adapter name, such as academic titles, ranks, or affiliations. Do not include the printer or publisher''s name, just the adapter''s description, if exists.', 0, 0);

